namespace sv_a1002931a41744db9c828b55323211b8.Client.Models;

public class Shipment
{
    public string TrackingNumber { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime? EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = new();
}

public class StatusUpdate
{
    public DateTime Timestamp { get; set; }
    public string Description { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
}

using sv_a1002931a41744db9c828b55323211b8.Client.Models;

namespace sv_a1002931a41744db9c828b55323211b8.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_a1002931a41744db9c828b55323211b8.Client.Models;

namespace sv_a1002931a41744db9c828b55323211b8.Client.Services;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _httpClient;

    public ShipmentHttpService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var shipment = await _httpClient.GetFromJsonAsync<Shipment>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        return shipment ?? throw new InvalidOperationException("Shipment not found.");
    }
}

using sv_a1002931a41744db9c828b55323211b8.Client.Models;
using sv_a1002931a41744db9c828b55323211b8.Client.Services;

namespace sv_a1002931a41744db9c828b55323211b8.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment
        {
            TrackingNumber = "TRK-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTime(2026, 7, 3, 17, 0, 0, DateTimeKind.Utc),
            StatusUpdates = new List<StatusUpdate>
            {
                new() { Timestamp = new DateTime(2026, 6, 27, 9, 0, 0, DateTimeKind.Utc), Description = "Package picked up", Location = "New York, NY" },
                new() { Timestamp = new DateTime(2026, 6, 28, 14, 30, 0, DateTimeKind.Utc), Description = "Departed facility", Location = "New York, NY" },
                new() { Timestamp = new DateTime(2026, 6, 29, 8, 15, 0, DateTimeKind.Utc), Description = "Arrived at sorting center", Location = "Chicago, IL" },
            }
        },
        ["TRK-002"] = new Shipment
        {
            TrackingNumber = "TRK-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTime(2026, 6, 28, 12, 0, 0, DateTimeKind.Utc),
            StatusUpdates = new List<StatusUpdate>
            {
                new() { Timestamp = new DateTime(2026, 6, 25, 10, 0, 0, DateTimeKind.Utc), Description = "Package picked up", Location = "Seattle, WA" },
                new() { Timestamp = new DateTime(2026, 6, 26, 6, 45, 0, DateTimeKind.Utc), Description = "In transit", Location = "Portland, OR" },
                new() { Timestamp = new DateTime(2026, 6, 27, 11, 0, 0, DateTimeKind.Utc), Description = "Out for delivery", Location = "San Francisco, CA" },
                new() { Timestamp = new DateTime(2026, 6, 27, 14, 22, 0, DateTimeKind.Utc), Description = "Delivered", Location = "San Francisco, CA" },
            }
        },
        ["TRK-003"] = new Shipment
        {
            TrackingNumber = "TRK-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTime(2026, 7, 5, 18, 0, 0, DateTimeKind.Utc),
            StatusUpdates = new List<StatusUpdate>
            {
                new() { Timestamp = new DateTime(2026, 6, 29, 16, 0, 0, DateTimeKind.Utc), Description = "Label created", Location = "Dallas, TX" },
            }
        },
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_a1002931a41744db9c828b55323211b8.Client.Models
@using sv_a1002931a41744db9c828b55323211b8.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_isLoading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@(_shipment.EstimatedDelivery?.ToString("f") ?? "N/A")</dd>
        </dl>

        @if (_shipment.StatusUpdates.Count > 0)
        {
            <h3>Tracking History</h3>
            <table>
                <thead>
                    <tr>
                        <th>Time</th>
                        <th>Description</th>
                        <th>Location</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                    {
                        <tr>
                            <td>@update.Timestamp.ToString("g")</td>
                            <td>@update.Description</td>
                            <td>@update.Location</td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Client.Models.Shipment? _shipment;
    private bool _isLoading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any previous in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _isLoading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || !ct.IsCancellationRequested)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task RetryLoad()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

